import{_ as t,o as i,c as o,a0 as s}from"./chunks/framework.ZNXClGez.js";const u=JSON.parse('{"title":"Admin Console","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/configuration-client-admin-console.md","filePath":"guide/deployment/configuration-client-admin-console.md"}'),a={name:"guide/deployment/configuration-client-admin-console.md"};function n(d,e,l,c,r,h){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="admin-console" tabindex="-1">Admin Console <a class="header-anchor" href="#admin-console" aria-label="Permalink to &quot;Admin Console&quot;">​</a></h1><p>The admin console is the administration surface: realms, clients, users, roles, permissions, policies, keys, sessions and the audit event log. It is a client-side single-page application (the <code>@authup/client-admin-console</code> package) served by <code>@authup/server-admin-console</code> on the IdP origin at <code>&lt;publicUrl&gt;/console/admin</code> by default, the same way the <a href="./account-console.html">account console</a> is served at <code>&lt;publicUrl&gt;/console/account</code>.</p><p>The bundle and the service that serves it are two packages. <code>authup start</code> runs that service in its own process alongside the API, on the API&#39;s listener, so a default deployment is still one container and one port; <code>authup console admin</code> runs it alone, on its own port, for a <a href="./console-replicas.html">split deployment</a>. Earlier releases shipped the console as a Nuxt server with its own environment variables, all of which are gone; see <a href="./upgrading.html">Upgrading</a> for what to remove from an existing setup.</p><h2 id="sign-in" tabindex="-1">Sign-in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign-in&quot;">​</a></h2><p>The console shares an origin with the API, so it signs in through the server. <code>GET /console/admin/login/start</code> starts an authorization-code flow with PKCE against the per-realm <code>admin-console</code> system client (see <a href="./provisioning.html#per-realm-system-clients">Provisioning</a>) and <code>GET /console/admin/callback</code> redeems the code. Those two are the only <code>/console/admin</code> paths the API answers; everything else under it is the console service. The browser keeps an opaque, <code>HttpOnly</code> session cookie; no OAuth2 token is handed to the page&#39;s JavaScript. The account console authenticates the same way, and both surfaces share the single session on that origin.</p><p>Binding an access policy to a realm&#39;s <code>admin-console</code> client (<code>accessPolicyId</code>) restricts who may newly sign in to the console. It gates admission (the authorization-code flow and code redemption), not tokens that were already issued. See the tip in <a href="./provisioning.html#per-realm-system-clients">Provisioning</a>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The console has its own section, <code>server.adminConsole</code>, in the one <a href="./configuration.html">configuration file</a>. Two of its options are the ones a single-container deployment ever needs; <code>url</code>, <code>port</code> and <code>host</code> matter for a <a href="./console-replicas.html">split deployment</a> and are documented there.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-9PywV" id="tab-KmnJmRx" checked><label data-title=".env" for="tab-KmnJmRx">.env</label><input type="radio" name="group-9PywV" id="tab-gvobRNg"><label data-title="authup.yml" for="tab-gvobRNg">authup.yml</label></div><div class="blocks"><div class="language-dotenv vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Serve the console at &lt;publicUrl&gt;/console/admin.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ADMIN_CONSOLE_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Package directory of a substituted console.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ADMIN_CONSOLE_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  adminConsole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span></span></code></pre></div></div></div><p><code>server.adminConsole.enabled</code> / <code>ADMIN_CONSOLE_ENABLED</code> (default <code>true</code>) turns the surface off. Both sides read it: <code>authup start</code> then mounts no admin console at all, and the API&#39;s two sign-in routes (<code>/console/admin/login/start</code>, <code>/console/admin/callback</code>) answer <code>404</code> rather than minting a session for a console nothing serves. <code>authup console admin</code> refuses to start for the same reason. The flag is also reported in the <code>features</code> block of the public status endpoint (<code>GET /</code>).</p><p><code>server.adminConsole.path</code> / <code>ADMIN_CONSOLE_PATH</code> replaces the served package. It points at a directory holding a built <code>dist/</code>, whose <code>index.html</code> must carry the <code>&lt;!--admin-config--&gt;</code> marker and whose assets must be built for the <code>/console/admin/</code> vite base. Neither is verified at boot: a shell without the marker still answers <code>200</code>, and the console silently falls back to deriving its API URL from its own origin. Empty resolves <code>@authup/client-admin-console</code> from <code>node_modules</code>. See <a href="./theming.html#replacing-a-console">Replacing a console</a>. For branding alone, use the <a href="./theming.html">theme directory</a> instead: it needs no build.</p><p>EXPERIMENTAL: point it at a source checkout instead, and <code>authup dev</code> (see the <a href="./../development/quick-start.html">Quick Start</a> guide) serves it from source with hot module replacement rather than reading <code>dist/</code>.</p><h2 id="standalone-hosting" tabindex="-1">Standalone hosting <a class="header-anchor" href="#standalone-hosting" aria-label="Permalink to &quot;Standalone hosting&quot;">​</a></h2><p>The console is an ordinary OAuth2 relying party, so the same built bundle can be hosted on any static host or another origin instead of (or in addition to) the embedded serving. The npm package ships <code>dist/</code> only: there is no binary and no process to run.</p><ol><li><p>Take the <code>dist/</code> directory of the <code>@authup/client-admin-console</code> package and serve it under a path of your host, <code>/console/admin</code> by default. Routing happens in the browser, so every path below that base has to serve the same <code>index.html</code>.</p></li><li><p>Inject the runtime configuration by replacing the <code>&lt;!--admin-config--&gt;</code> marker in <code>index.html</code> (or by any script that runs before the app bundle):</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.__AUTHUP__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;apiUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://auth.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;basePath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/console/admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>apiUrl</code> is the authup server&#39;s public URL. Without injected configuration the app assumes it is served by (or proxied to) the authup origin itself and derives the API URL from its own location. When you build the bundle from source, <code>VITE_API_URL</code> bakes the value in at build time instead. The optional <code>clientId</code> defaults to <code>admin-console</code>; set it only for a fork that registers its own OAuth2 client.</p></li><li><p>Register the host&#39;s origin in the authup server&#39;s <a href="./configuration-server-core.html"><code>TRUSTED_ORIGINS</code></a>. The per-realm <code>admin-console</code> client&#39;s redirect and post-logout allowlists derive from that origin set, so the sign-in and sign-out round-trips are permitted on the next start.</p></li></ol><p>On a foreign origin the server-side session cookie does not apply: it is <code>SameSite=Strict</code> and scoped to the API&#39;s own origin. The console then uses the browser-side authorization-code flow with PKCE and keeps its tokens in JavaScript. That is decided at runtime from the injected configuration, not configured.</p><h2 id="retired-environment-variables" tabindex="-1">Retired environment variables <a class="header-anchor" href="#retired-environment-variables" aria-label="Permalink to &quot;Retired environment variables&quot;">​</a></h2><p>The console had its own runtime configuration while it ran as a server. None of the following is read any more, and none has a successor:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Why it is gone</th></tr></thead><tbody><tr><td><code>NUXT_PUBLIC_API_URL</code>, <code>API_URL</code>, <code>API_URL_SERVER</code></td><td>The API is the serving origin, or <code>window.__AUTHUP__.apiUrl</code> when hosted standalone.</td></tr><tr><td><code>NUXT_PUBLIC_PUBLIC_URL</code></td><td><code>ADMIN_CONSOLE_URL</code>, which defaults to <code>&lt;publicUrl&gt;/console/admin</code> and may change the path but not the origin.</td></tr><tr><td><code>NUXT_PUBLIC_COOKIE_DOMAIN</code></td><td>The console is same-origin with the API, so there is no cookie domain to widen.</td></tr><tr><td><code>NUXT_PUBLIC_CLIENT_ID</code></td><td>The client is <code>admin-console</code>. A fork injects <code>clientId</code> in <code>window.__AUTHUP__</code>.</td></tr><tr><td><code>NUXT_HOST</code>, <code>NUXT_PORT</code></td><td><code>ADMIN_CONSOLE_HOST</code> / <code>ADMIN_CONSOLE_PORT</code>, the listener <code>authup console</code> binds.</td></tr></tbody></table><p>The plain build-time names <code>PUBLIC_URL</code>, <code>COOKIE_DOMAIN</code> and <code>CLIENT_ID</code> are gone with them. Note that <code>PUBLIC_URL</code> is unrelated to the console and stays a <a href="./configuration-server-core.html"><code>server/core</code> option</a>: it is the public URL of the server, and the console&#39;s own address derives from it.</p><p>The <code>client.admin-console</code> section of the configuration file is no longer read either, and <code>authup start client.admin-console</code> is refused: <code>start</code> takes no positional argument. The command that does is <code>authup console [admin|account|auth]</code>, which serves a console rather than selecting a package.</p>`,21)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
